solution.exercise.c:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
uint64_t private_key(uint64_t p,uint64_t*s){if(p<=2)return 0;*s=*s*6364136223846793005ULL+1442695040888963407ULL;return 2+(*s>>1)%(p-2);}static uint64_t mul(uint64_t a,uint64_t b,uint64_t m){uint64_t r=0;while(b){if(b&1)r=r>=m-a?r-(m-a):r+a;b>>=1;a=a>=m-a?a-(m-a):a+a;}return r;}uint64_t public_key(uint64_t p,uint64_t g,uint64_t k){if(p<2)return 0;uint64_t r=1;g%=p;while(k){if(k&1)r=mul(r,g,p);g=mul(g,g,p);k>>=1;}return r;}uint64_t secret(uint64_t p,uint64_t g,uint64_t k){return public_key(p,g,k);}

