uint64_t rng=123;for(int i=0;i<100;i++){uint64_t k=private_key(23,&rng);assert(k>1&&k<23);}assert(public_key(23,5,6)==8);assert(public_key(23,5,15)==19);assert(secret(23,19,6)==2);assert(secret(23,8,15)==2);assert(public_key(23,5,0)==1);

